  "package": "@astryxdesign/core",
  "data": {
    "template": "TimeInputShowcase",
    "description": "A time input that uses the browser/OS picker on touch by default and Astryx typed entry on fine pointers.",
    "type": "block",
    "components": [
      "Stack",
      "TimeInput"
    ],
    "source": "// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {TimeInput, type ISOTimeString} from '@astryxdesign/core/TimeInput';\nimport {Stack} from '@astryxdesign/core/Layout';\n\nexport default function TimeInputShowcase() {\n  const [time, setTime] = useState<ISOTimeString | undefined>(undefined);\n  return (\n    <Stack\n      direction=\"vertical\"\n      width=\"100%\"\n      style={{minWidth: 240, maxWidth: 400}}>\n      <TimeInput\n        label=\"Time\"\n        placeholder=\"Select a time\"\n        value={time}\n        onChange={setTime}\n      />\n    </Stack>\n  );\n}\n",
    "demoMediaReplaced": 0,
    "demoContentReplaced": 0
  },
